import { useEffect, useState } from 'react';
import Head from 'next/head';
import { adminFetch, adminMutation, apiErrorMessage } from '@/lib/admin-client';

type User = { id: string; full_name?: string; email?: string; phone?: string; role?: string; suspended?: boolean; active?: boolean };
type Session = { id: string; target_user_id: string; target_role: string; status: string; reason: string; expiresAt: string; createdAt: string };
type StartResponse = { session_id: string; target: User; expires_at: string; warning: string };
type SupportContext = { active: true; read_only: true; session_id: string; expires_at: string; target: { id: string; role: string }; impersonator: { id: string; role: string } };

export default function ImpersonationPage() {
  const [query, setQuery] = useState(''); const [users, setUsers] = useState<User[]>([]); const [sessions, setSessions] = useState<Session[]>([]); const [selected, setSelected] = useState<User | null>(null); const [reason, setReason] = useState(''); const [active, setActive] = useState<StartResponse | null>(null); const [loading, setLoading] = useState(false); const [busy, setBusy] = useState(false); const [error, setError] = useState('');
  async function loadUsers() { if (!query.trim()) { setUsers([]); return; } setLoading(true); try { const result = await adminFetch<any>(`/users?q=${encodeURIComponent(query.trim())}&limit=25`); setUsers(Array.isArray(result) ? result : result.data || []); } catch (cause) { setError(apiErrorMessage(cause, 'تعذر البحث عن المستخدمين.')); } finally { setLoading(false); } }
  async function loadSessions() { try { const result = await adminFetch<{ data: Session[] }>('/impersonation'); setSessions(result.data || []); } catch (cause) { setError(apiErrorMessage(cause, 'تعذر تحميل جلسات الدعم.')); } }
  useEffect(() => { const timer = window.setTimeout(() => void loadUsers(), 300); return () => window.clearTimeout(timer); }, [query]);
  useEffect(() => { void loadSessions(); }, []);
  async function start() { if (!selected || reason.trim().length < 5) { setError('اختر مستخدماً واكتب سبباً لا يقل عن خمسة أحرف.'); return; } if (!window.confirm(`سيتم إنشاء جلسة دعم قصيرة للمستخدم «${selected.full_name || selected.id}». متابعة؟`)) return; setBusy(true); setError(''); try { const result = await adminMutation<StartResponse>('/impersonation/start', 'POST', { user_id: selected.id, minutes: 15, reason: reason.trim() }); const context = await adminFetch<SupportContext>('/impersonation/context'); if (!context.active || !context.read_only || context.session_id !== result.session_id || context.target.id !== result.target.id) throw new Error('support_session_context_invalid'); setActive(result); setReason(''); await loadSessions(); } catch (cause) { setError(apiErrorMessage(cause, 'تعذر إنشاء أو إثبات جلسة الدعم.')); } finally { setBusy(false); } }
  async function revoke(id: string) { const revokeReason = window.prompt('سبب إبطال جلسة الدعم:'); if (!revokeReason || revokeReason.trim().length < 5) return; setBusy(true); setError(''); try { await adminMutation('/impersonation/revoke', 'POST', { session_id: id, reason: revokeReason.trim() }); await loadSessions(); if (active?.session_id === id) setActive(null); } catch (cause) { setError(apiErrorMessage(cause, 'تعذر إبطال الجلسة.')); } finally { setBusy(false); } }
  return <><Head><title>جلسات الدعم | نبض</title></Head><section dir="rtl" className="space-y-6 p-6 md:p-8"><header><h1 className="text-3xl font-bold">جلسات الدعم المقيّدة</h1><p className="mt-1 text-sm text-slate-500">السياق محفوظ في HttpOnly cookie ولا يظهر token في الواجهة أو DOM. الجلسة للمستخدمين غير الإداريين فقط وبمدة قصوى 15 دقيقة، وهي قراءة فقط ولا تفوض عمليات مالية أو طبية أو إدارية عالية الخطورة.</p></header>{error ? <p role="alert" className="rounded-lg bg-rose-50 p-3 text-rose-700">{error}</p> : null}{active ? <article className="rounded-2xl border border-amber-300 bg-amber-50 p-5" role="status"><h2 className="font-bold text-amber-900">جلسة دعم مفعّلة للمستخدم {active.target.full_name || active.target.id}</h2><p className="mt-2 text-sm text-amber-800">{active.warning} تنتهي في {new Date(active.expires_at).toLocaleString('ar-SA')}، ويمكن إبطالها من سجل الجلسات.</p><button onClick={() => setActive(null)} className="mt-3 rounded border px-3 py-1 text-sm">إخفاء الشريط</button></article> : null}<div className="grid gap-6 lg:grid-cols-2"><article className="rounded-2xl border bg-white p-5 shadow-sm"><h2 className="text-xl font-bold">بدء جلسة دعم</h2><input value={query} onChange={(e) => setQuery(e.target.value)} className="mt-4 w-full rounded border p-2" placeholder="ابحث بالاسم أو الهاتف أو البريد"/>{loading ? <p className="mt-3 text-sm text-slate-500">جارٍ البحث…</p> : <ul className="mt-3 divide-y">{users.map((user) => <li key={user.id} className={`flex items-center justify-between gap-3 py-3 ${selected?.id === user.id ? 'bg-teal-50' : ''}`}><div><strong>{user.full_name || user.id}</strong><p className="text-xs text-slate-500" dir="ltr">{user.email || user.phone || user.id} · {user.role}</p></div><button disabled={user.suspended === true || user.active === false} onClick={() => setSelected(user)} className="rounded border px-3 py-1 text-xs disabled:opacity-40">اختيار</button></li>)}</ul>}<p className="mt-4 text-sm">المحدد: <strong>{selected?.full_name || selected?.id || 'لا يوجد'}</strong></p><textarea value={reason} onChange={(e) => setReason(e.target.value)} minLength={5} className="mt-3 min-h-20 w-full rounded border p-2" placeholder="سبب جلسة الدعم والتذكرة المرتبطة بها"/><button disabled={busy || !selected} onClick={() => void start()} className="mt-3 rounded bg-teal-700 px-4 py-2 font-bold text-white disabled:opacity-50">إنشاء جلسة 15 دقيقة</button></article><article className="rounded-2xl border bg-white p-5 shadow-sm"><h2 className="text-xl font-bold">سجل الجلسات</h2><ul className="mt-3 divide-y">{sessions.length ? sessions.map((session) => <li key={session.id} className="py-3"><div className="flex items-center justify-between gap-3"><strong className="font-mono text-xs">{session.id}</strong>{session.status === 'active' ? <button disabled={busy} onClick={() => void revoke(session.id)} className="rounded border border-rose-300 px-2 py-1 text-xs text-rose-700">إبطال</button> : <span className="text-xs text-slate-500">{session.status}</span>}</div><p className="mt-1 text-xs text-slate-500">المستخدم: {session.target_user_id} · تنتهي: {new Date(session.expiresAt).toLocaleString('ar-SA')}</p><p className="mt-1 text-xs text-slate-500">السبب: {session.reason}</p></li>) : <li className="py-6 text-sm text-slate-500">لا توجد جلسات دعم.</li>}</ul></article></div></section></>;
}
